<?php
require_once __DIR__.'/../config/auth.php'; ensure_assessment_tables();require_admin();$id=(int)($_GET['id']??$_POST['id']??0);$s=db()->prepare('SELECT * FROM provas WHERE id=?');$s->execute([$id]);$prova=$s->fetch();if(!$prova)exit('Prova não encontrada.');$hasAttempts=db()->prepare('SELECT COUNT(*) FROM prova_tentativas WHERE prova_id=?');$hasAttempts->execute([$id]);if((int)$hasAttempts->fetchColumn()>0)exit('Esta prova já possui tentativas. Para preservar o histórico, não é permitido editar suas questões.');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$title=trim($_POST['titulo']);$subject=trim($_POST['disciplina']);$duration=max(1,min(300,(int)$_POST['duracao']));if(!$title||!$subject)throw new RuntimeException('Título e disciplina são obrigatórios.');db()->beginTransaction();$u=db()->prepare('UPDATE provas SET titulo=?,disciplina=?,descricao=?,duracao_minutos=?,publicada=? WHERE id=?');$u->execute([$title,$subject,trim($_POST['descricao']),$duration,isset($_POST['publicada'])?1:0,$id]);db()->prepare('DELETE FROM prova_perguntas WHERE prova_id=?')->execute([$id]);$q=db()->prepare('INSERT INTO prova_perguntas(prova_id,pergunta,alternativa_a,alternativa_b,alternativa_c,alternativa_d,correta) VALUES(?,?,?,?,?,?,?)');foreach($_POST['pergunta'] as $i=>$text){$text=trim($text);if($text==='')continue;$vals=[trim($_POST['a'][$i]??''),trim($_POST['b'][$i]??''),trim($_POST['c'][$i]??''),trim($_POST['d'][$i]??'')];if(in_array('', $vals,true))throw new RuntimeException('Preencha todas as alternativas das questões usadas.');$q->execute([$id,$text,$vals[0],$vals[1],$vals[2],$vals[3],$_POST['correta'][$i]??'a']);}db()->commit();flash('success','Prova atualizada.');redirect('admin/provas.php');}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$error=$e->getMessage();}}
$p=db()->prepare('SELECT * FROM prova_perguntas WHERE prova_id=? ORDER BY id');$p->execute([$id]);$questions=$p->fetchAll();$pageTitle='Editar prova';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/dashboard-nav.php';
?><form class="panel" method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><h2>Editar prova</h2><?php if(!empty($error)):?><div class="notice error"><?=e($error)?></div><?php endif;?><div class="form-grid"><div class="form-group"><label>Título</label><input required name="titulo" value="<?=e($prova['titulo'])?>"></div><div class="form-group"><label>Disciplina</label><input required name="disciplina" value="<?=e($prova['disciplina'])?>"></div><div class="form-group"><label>Duração</label><input type="number" min="1" max="300" name="duracao" value="<?=$prova['duracao_minutos']?>"></div><div class="form-group" style="padding-top:26px"><label><input type="checkbox" name="publicada" <?=$prova['publicada']?'checked':''?>> Publicada</label></div></div><div class="form-group"><label>Descrição</label><textarea name="descricao"><?=e($prova['descricao'])?></textarea></div><div id="questoes"><?php foreach($questions as $i=>$q):?><fieldset style="border:1px solid #d9e2ec;border-radius:10px;margin:14px 0;padding:14px"><legend>Questão <?=$i+1?></legend><div class="form-group"><label>Enunciado</label><textarea required name="pergunta[<?=$i?>]"><?=e($q['pergunta'])?></textarea></div><div class="form-grid"><?php foreach(['a','b','c','d'] as $l):?><div class="form-group"><label>Alternativa <?=strtoupper($l)?></label><input required name="<?=$l?>[<?=$i?>]" value="<?=e($q['alternativa_'.$l])?>"></div><?php endforeach;?></div><div class="form-group"><label>Correta</label><select name="correta[<?=$i?>]"><?php foreach(['a','b','c','d'] as $l):?><option value="<?=$l?>" <?=$q['correta']===$l?'selected':''?>><?=strtoupper($l)?></option><?php endforeach;?></select></div></fieldset><?php endforeach;?></div><button type="button" class="btn btn-outline" onclick="addQuestion()">＋ Adicionar questão</button> <button class="btn">Salvar alterações</button></form><script>let n=<?=count($questions)?>;function addQuestion(){const i=n++;const b=document.createElement('fieldset');b.style='border:1px solid #d9e2ec;border-radius:10px;margin:14px 0;padding:14px';b.innerHTML=`<legend>Questão ${i+1}</legend><div class="form-group"><label>Enunciado</label><textarea required name="pergunta[${i}]"></textarea></div><div class="form-grid">${['a','b','c','d'].map(l=>`<div class="form-group"><label>Alternativa ${l.toUpperCase()}</label><input required name="${l}[${i}]"></div>`).join('')}</div><div class="form-group"><label>Correta</label><select name="correta[${i}]"><option value="a">A</option><option value="b">B</option><option value="c">C</option><option value="d">D</option></select></div>`;document.getElementById('questoes').appendChild(b)}</script><?php require __DIR__.'/../includes/dashboard-footer.php';?>
